   assert.deepEqual([...home().children].map(n=>n.tagName),['HEADER','SECTION']);assert(p.q('.sk-home-heading h1'));assert.match(p.q('.sk-home-heading [data-sk-action=new]').textContent,/New game/i);assert.match(p.q('.sk-ongoing h2').textContent,/Ongoing games/i);
   assert.equal(p.all('.sk-intro,.sk-quick-layout,.sk-rosters,.reference-workspace-summary,.cmd-reference-skirmish').length,0);
   assert.equal(home().querySelectorAll('[data-sk-action=new]').length,1);assert.equal(home().querySelectorAll('[data-sk-action=delete],[data-sk-action=help]').length,0);
   assert.deepEqual(p.all('.sk-match-list [data-sk-action=open]').map(n=>n.dataset.skId).sort(),['home-battle','home-setup']);assert.equal(p.all('.sk-match').length,2);assert(!home().textContent.includes('Completed authored game'));assert(!home().textContent.includes('Incomplete authored game'));
