 await test('Challenge validation stays rejected while the error is shown next to Save, can be dismissed and reappears on another failed attempt',async()=>{const p=await page();try{campaignFixture(p);p.run(`cpReportModal({id:'invalid-draft',name:'Saved draft',challenge:true,status:'Issued',date:'2026-10-31',cycle:2,participants:[{gangId:'verified-gang'},{gangId:'verified-gang'}],notes:'Keep authored input'})`);const before=p.snapshot();p.tap('#modal-submit');await tick();await tick();assert.match(p.q('.modal-foot [data-ux-feedback]').textContent,/different gangs/);assert(p.q('.cp-error').classList.contains('ux-error-source'));assert.equal(p.q('#modal-form').elements.notes.value,'Keep authored input');assert.equal(p.snapshot(),before);p.tap('.ux-error-close');await tick();assert.equal(p.all('[data-ux-feedback]').length,0);p.tap('#modal-submit');await tick();await tick();assert.match(p.q('.modal-foot [data-ux-feedback]').textContent,/different gangs/);p.tap('#modal-cancel');await tick();await tick();p.run('editGang(gang())');await tick();assert.equal(p.all('[data-ux-feedback]').length,0,'An old dialog failure never appears in a new dialog');p.tap('#modal-cancel');assert.equal(p.snapshot(),before);assert.deepEqual(p.errors,[]);}finally{p.close();}});
 await test('Native invalid fields preserve values and constraints, connect inline feedback, and focus the first field; background failures surface in the active dialog',async()=>{const p=await page();try{campaignFixture(p);p.run(`window.__savedCount=0;formModal('Required fields','<label>First name<input name="first" required aria-describedby="existing-help"></label><small id="existing-help">Keep help</small><label>Second name<input name="second" required></label>',()=>{window.__savedCount++;return false})`);p.tap('#modal-submit');await new Promise(r=>setTimeout(r,35));assert.equal(p.w.__savedCount,0);assert.equal(p.q('[name=first]').getAttribute('aria-invalid'),'true');assert.match(p.q('[name=first]').getAttribute('aria-describedby'),/existing-help.*ux-field-error/);assert.equal(p.w.document.activeElement,p.q('[name=first]'));assert(p.q('.modal-foot [data-ux-feedback]'));p.set('first','Kept first');p.set('second','Kept second');await tick();await tick();assert.equal(p.all('[data-ux-field-error]').length,0);assert.equal(p.q('[name=first]').getAttribute('aria-describedby'),'existing-help');assert.equal(p.q('[name=first]').getAttribute('aria-invalid'),null);assert.equal(p.all('[data-ux-feedback]').length,0);p.run(`MMCampaignAutomation.notify('Async save failed',true)`);await tick();await tick();assert.match(p.q('.modal-foot [data-ux-feedback]').textContent,/Async save failed/);assert.equal(p.q('[name=first]').value,'Kept first');p.tap('#modal-cancel');await tick();await tick();assert(p.q('.ux-page-error'));p.tap('.ux-error-close');await tick();p.run(`formModal('Another dialog','<input name="keep" value="Keep second dialog">',()=>false);MMCampaignAutomation.notify('Async save failed',true)`);await tick();await tick();assert.match(p.q('.modal-foot [data-ux-feedback]').textContent,/Async save failed/);assert.equal(p.all('.ux-page-error:not([hidden])').length,0);p.run(`MMCampaignAutomation.notify('Saved',false)`);await tick();await tick();assert.equal(p.all('[data-ux-feedback]').length,0,'A success notification clears the prior error');p.tap('#modal-cancel');assert.deepEqual(p.errors,[]);}finally{p.close();}});
 await test('Thrown synchronous and asynchronous modal saves stay inside the dialog without browser alerts or lost input',async()=>{const p=await page();try{const before=p.snapshot();p.run(`window.__saveTries=0;formModal('Throwing save','<label>Name<input name="keep" value="Keep this draft"></label>',()=>{window.__saveTries++;throw Error('No eligible Active fighters');})`);p.tap('#modal-submit');await tick();await tick();assert.equal(p.alerts.length,0);assert.match(p.q('.modal-foot [data-ux-feedback]').textContent,/No eligible Active fighters/);assert.equal(p.q('[name=keep]').value,'Keep this draft');assert.equal(p.q('#modal-submit').disabled,false);p.tap('.modal-foot .ux-error-close');p.tap('#modal-submit');await tick();await tick();assert.match(p.q('.modal-foot [data-ux-feedback]').textContent,/No eligible/);assert.equal(p.w.__saveTries,2);p.tap('#modal-cancel');p.run(`formModal('Async failure','<label>Name<input name="keep" value="Keep async draft"></label>',async()=>{throw Error('Latest roster is unavailable');})`);p.tap('#modal-submit');await tick();await tick();assert.equal(p.alerts.length,0);assert.match(p.q('.modal-foot [data-ux-feedback]').textContent,/Latest roster is unavailable/);p.run("MMCampaignAutomation.notify('Latest roster is unavailable',true)");await tick();await tick();assert.equal((p.q('.modal-foot [data-ux-feedback]').textContent.match(/Latest roster is unavailable/g)||[]).length,1,'The operation notice and modal exception appear only once');p.run("MMCampaignAutomation.notify('',false)");assert.equal(p.q('[name=keep]').value,'Keep async draft');assert.equal(p.q('#modal-submit').disabled,false);assert.equal(p.snapshot(),before);p.tap('#modal-cancel');await tick();await tick();assert.equal(p.all('[data-ux-feedback]').length,0);assert.deepEqual(p.errors,[]);}finally{p.close();}});
 await test('All campaign source routes keep the same primary tabs, admin navigation retains its dialog, and battle Back returns to the selected category',async()=>{const p=await page();try{campaignFixture(p);const tabs=()=>p.all('.cmd-reference-campaign [data-ref-tab]').map(n=>n.dataset.refTab);const expected=tabs();for(const tab of ['territories','battles','pack','map','triumphs','members']){p.run('data.campaignTab='+JSON.stringify(tab)+';render()');assert.deepEqual(tabs(),expected);assert.equal(p.all('.cmd-reference-extra').length,0);}p.tap('[data-ref-tab=history]');p.all('.cmd-reference-campaign .heading-actions button').at(-1).click();for(const tab of ['battles','territories','map','pack','triumphs','members']){p.tap('.cmd-legacy-controls [data-campaign-tab='+tab+']');assert(p.q('.cmd-legacy-controls').hasAttribute('data-ref-open'));assert.equal(p.q('.cmd-reference-campaign').inert,true);assert.deepEqual(tabs(),expected);}p.tap('[data-ref-close]');assert.equal(p.q('.section-tabs [aria-selected=true]').dataset.refTab,'history');p.run(`campaign().sessions=[{id:'return-session',round:1,stage:'battle',status:'Active',cycle:2,scenario:'Saved battle',participants:data.gangs.map((g,i)=>({id:'return-p'+i,gangId:g.id,role:i?'defender':'attacker',crew:[],resources:{},creditsEarned:0,reputationChange:0}))}];sessionDetail(campaign().sessions[0])`);const records=p.run('JSON.stringify([data.gangs,data.campaigns])');p.tap('[data-cp=session-back]');assert.deepEqual(tabs(),expected);assert.equal(p.q('.section-tabs [aria-selected=true]').dataset.refTab,'history');assert.equal(p.q('.cmd-legacy-controls').hasAttribute('data-ref-open'),false);assert.equal(p.run('JSON.stringify([data.gangs,data.campaigns])'),records);assert.deepEqual(p.errors,[]);}finally{p.close();}});
 await test('Challenge shortcut stays inline, cancellation keeps the command page, and completing an order unlocks its native next action',async()=>{const p=await page();try{campaignFixture(p);p.w.AccountParity={account:null,ready:false,connecting:false,busy:false};p.run(`campaign().members.forEach((m,i)=>m.player='Distinct player '+i);render()`);const before=p.run('JSON.stringify([data.gangs,data.campaigns])');p.tap('.compact-notice button');assert(p.q('.cmd-reference-campaign [data-ca-challenges]'));assert.equal(p.q('.cmd-legacy-controls').hasAttribute('data-ref-open'),false);for(const tab of ['gangs','territories','history','progress'])p.tap('[data-ref-tab='+tab+']');assert(p.q('.cmd-reference-campaign [data-ca-challenges]'));assert.equal(p.run('JSON.stringify([data.gangs,data.campaigns])'),before);p.tap('.cmd-reference-campaign [data-ca-action=open-cycle]');p.tap('#modal-cancel');assert.equal(p.run('JSON.stringify([data.gangs,data.campaigns])'),before);p.tap('.cmd-reference-campaign [data-ca-action=open-cycle]');p.tap('#modal-submit');for(let n=0;n<80&&!p.run('campaign().automation?.cycleRecords?.["2"]');n++)await tick();await tick();await tick();assert(p.run('campaign().automation.cycleRecords["2"]'));assert.equal(p.q('.cmd-reference-campaign .ca-current-task [data-ca-action=issue]').disabled,false);assert.equal(p.run('campaign().currentCycle'),2);assert.equal(p.q('.cmd-legacy-controls').hasAttribute('data-ref-open'),false);assert.deepEqual(p.errors,[]);}finally{p.close();}});
